function header(){let signedIn=window.NegosyoDepotAuth?.signedIn===true;return `<div class="fulfillment-topbar"><div class="container topbar-inner"><a href="#/fulfillment/network"><span class="topbar-star">✦</span> Local fulfillment, powered by FLAME PH MSMEs. <strong>Explore the network →</strong></a><a class="topbar-search" href="#/explore?focus=search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg>Search</a></div></div><header class="site-header"><div class="container header-row"><a class="brand" href="#/" aria-label="NegosyoDepot home"><img class="brand-image header-logo" src="/assets/negosyodepot-logo.png" alt="NegosyoDepot.com" /></a><button class="icon-btn" id="menuToggle" aria-label="Open menu" aria-expanded="false">☰</button><nav class="nav mega-navigation" id="nav">${fulfillmentMegaMenus()}</nav><div class="header-actions">${signedIn?`<button class="btn btn-outline header-auth-toggle" type="button" data-mobile-signout>♙ Log out</button>`:`<a href="#/login" class="btn btn-outline" data-open-signup>♙ Log in</a>`}<a href="#/login" class="btn btn-primary" data-open-signup>Start selling</a><a class="btn btn-soft desktop-flame-ai" href="https://flameph.org/bizconsult-ai" target="_blank" rel="noopener noreferrer" aria-label="Open KA FLAME AI on FLAME PH">✦ FLAME AI</a></div><div class="mobile-header-actions"><a class="mobile-flame-ai" href="https://flameph.org/bizconsult-ai" target="_blank" rel="noopener noreferrer" aria-label="Open KA FLAME AI" title="KA FLAME AI"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 14 9l6 2-6 2-2 7-2-7-6-2 6-2z"/></svg><span>FLAME AI</span></a><button class="mobile-search-btn" data-mobile-search aria-label="Search negosyo opportunities" title="Search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg></button><a class="mobile-signup-btn" href="#/login" data-open-signup>Sign-up Free</a>${signedIn?`<button class="mobile-auth-toggle" type="button" data-mobile-signout>Sign Out</button>`:`<a class="mobile-auth-toggle" href="#/login" data-open-signup>Sign In</a>`}</div></div></header>`}
