function signupDialog(){return `<div class="signup-backdrop" data-signup-backdrop hidden><section class="signup-dialog" role="dialog" aria-modal="true" aria-labelledby="signup-title"><div class="signup-visual"><div class="signup-visual-copy"><span class="section-kicker">One FLAMEPH Member ID</span><h2>Build your next business move with the FLAME PH ecosystem.</h2><p>Discover local fulfillment, business opportunities, and practical support for MSMEs.</p></div><div class="signup-orbit" aria-hidden="true"><span>MSME</span><b>↗</b><i>FLAME PH</i></div></div><div class="signup-form-side"><button class="signup-close" type="button" data-close-signup aria-label="Close signup dialog">×</button><span class="section-kicker">Welcome to NegosyoDepot</span><h2 id="signup-title">Sign in or create account</h2><a class="btn btn-outline signup-provider" href="https://www.flameph.org/join" target="_blank" rel="noopener noreferrer">Create a free FLAME PH account</a><div class="signup-divider"><span>OR</span></div><div class="signup-tabs" role="tablist"><button type="button" class="active" data-dialog-mode="email" role="tab" aria-selected="true">Email</button><button type="button" data-dialog-mode="mobile" role="tab" aria-selected="false">Mobile number</button></div><form id="quickSignupForm"><label class="sr-only" for="quickSignupIdentity" id="quickSignupLabel">Email address</label><input id="quickSignupIdentity" name="identity" type="email" autocomplete="email" placeholder="Enter your email address" required><label class="invite-code-label"><input type="checkbox" id="showInviteCode"> I have an invite code</label><input id="inviteCode" name="invite" placeholder="Invite code (optional)" hidden><button class="btn btn-primary signup-continue" type="submit">Continue securely</button></form><p class="signup-legal">By continuing, you agree to the <a href="#/terms">Terms</a> and <a href="#/privacy">Privacy Notice</a>. In production, verification runs through FLAME PH identity. This preview does not send codes or create accounts.</p><button class="signup-help" type="button" data-dialog-login>Already a member? Sign in</button></div></section></div>`}
function mobileDock(){return `<nav class="mobile-dock" aria-label="Quick navigation"><a class="dock-item ${current==="/explore"||current==="/find"?"active":""}" href="#/explore"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><span>Find Business</span></a><a class="dock-item ${current==="/sell-business"?"active":""}" href="#/sell-business"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v13H4zM8 7V4h8v3M8 12h8M8 16h5"/></svg><span>Sell Business</span></a><a class="dock-item dock-post ${current==="/post"?"active":""}" href="#/post"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg><span>Post Business</span></a><a class="dock-item ${current.startsWith("/fulfillment")?"active":""}" href="#/fulfillment"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h11v11H3zM14 11h4l3 3v4h-7z"/><circle cx="7.5" cy="19" r="1.5"/><circle cx="18" cy="19" r="1.5"/></svg><span>Fulfillment</span></a><a class="dock-item ${current==="/funder-finder"?"active":""}" href="#/funder-finder"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19V5M4 19h17M8 15l4-4 3 2 5-6M16 7h4v4"/></svg><span>Funder Finder</span></a></nav>`}
function layout(body){app.innerHTML=header()+`<main id="main" class="main">${body}</main>`+footer()+signupDialog()+mobileDock();document.querySelectorAll(`.nav a[href="#${current}"]`).forEach(a=>a.classList.add("active"));document.getElementById("menuToggle")?.addEventListener("click",e=>{let nav=document.getElementById("nav"),open=nav.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",String(open))});document.getElementById("nav")?.addEventListener("toggle",e=>{let opened=e.target;if(opened instanceof HTMLDetailsElement&&opened.open)document.querySelectorAll("#nav details.mega-menu[open]").forEach(item=>{if(item!==opened)item.open=false})},true);document.querySelector("[data-mobile-search]")?.addEventListener("click",()=>{location.hash="/explore?focus=search"});document.querySelectorAll("[data-open-signup]").forEach(b=>b.addEventListener("click",e=>{e.preventDefault();openSignup()}));document.querySelector("[data-close-signup]")?.addEventListener("click",closeSignup);document.querySelector("[data-signup-backdrop]")?.addEventListener("click",e=>{if(e.target===e.currentTarget)closeSignup()});document.querySelectorAll("[data-dialog-mode]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-dialog-mode]").forEach(x=>{x.classList.toggle("active",x===b);x.setAttribute("aria-selected",String(x===b))});let mobile=b.dataset.dialogMode==="mobile",input=document.getElementById("quickSignupIdentity");input.type=mobile?"tel":"email";input.autocomplete=mobile?"tel":"email";input.placeholder=mobile?"Enter your mobile number":"Enter your email address";document.getElementById("quickSignupLabel").textContent=mobile?"Mobile number":"Email address";input.focus()}));document.getElementById("showInviteCode")?.addEventListener("change",e=>{let field=document.getElementById("inviteCode");field.hidden=!e.target.checked;if(!field.hidden)field.focus()});document.getElementById("quickSignupForm")?.addEventListener("submit",e=>{e.preventDefault();let value=document.getElementById("quickSignupIdentity").value.trim(),mode=document.getElementById("quickSignupIdentity").type==="tel"?"mobile":"email",invite=document.getElementById("inviteCode").value.trim();closeSignup();location.hash=`/login?method=${mode}&identity=${encodeURIComponent(value)}&invite=${encodeURIComponent(invite)}`});document.querySelector("[data-dialog-login]")?.addEventListener("click",()=>{closeSignup();location.hash="/login"});document.querySelectorAll("[data-mobile-signout]").forEach(b=>b.addEventListener("click",async()=>{let auth=window.NegosyoDepotAuth;if(typeof auth?.signOutEverywhere==="function")await auth.signOutEverywhere();else if(typeof auth?.signOut==="function")await auth.signOut();else return;page()}));bindCommon();bindFundingTools();bindInvestorTools();bindWorkspaceTools();if(current==="/explore"&&new URLSearchParams(location.hash.split("?")[1]||"").get("focus")==="search")requestAnimationFrame(()=>document.getElementById("exploreQuery")?.focus())}
function openSignup(){let d=document.querySelector("[data-signup-backdrop]");if(!d)return;d.hidden=false;document.body.classList.add("dialog-open");setTimeout(()=>document.getElementById("quickSignupIdentity")?.focus(),20)}
function closeSignup(){let d=document.querySelector("[data-signup-backdrop]");if(!d)return;d.hidden=true;document.body.classList.remove("dialog-open")}
function bindFulfillmentTools(){let form=document.getElementById("fulfillmentEstimator");if(form){let update=()=>{let orders=Number(document.getElementById("estimateOrders").value)||0,rates=["estimateReceive","estimateStorage","estimatePick","estimateDelivery"].map(id=>Number(document.getElementById(id).value)||0),perOrder=rates.reduce((a,b)=>a+b,0),total=orders*perOrder;document.getElementById("estimateTotal").textContent=money(total.toFixed(2));document.getElementById("estimateBreakdown").textContent=`${orders.toLocaleString()} orders × ${money(perOrder.toFixed(2))} in entered service rates per order. Taxes, minimum charges, and exceptions are excluded.`};form.addEventListener("input",update);update()}}
function card(x){return `<article class="listing-card"><div class="listing-image"><img src="${x.img}" alt="${x.cat} business opportunity" loading="lazy"><span class="listing-badge">${x.tag}</span><button class="save-btn" aria-label="Save ${x.name}" data-save="${x.id}">♡</button></div><div class="listing-body"><div class="listing-meta"><span>${x.cat} · ${x.model}</span><span>📍 ${x.city}</span></div><h3>${link("/opportunity/"+x.id,x.name)}</h3><p>${x.desc}</p><div class="listing-meta"><span class="verified">✓ Seller details reviewed</span><span>Sample listing</span></div><div class="listing-price"><div><small>Package from</small><strong>${money(x.price)}</strong></div><div class="listing-actions"><button class="btn btn-soft" data-compare="${x.id}">Compare</button><a class="btn btn-primary" href="#/opportunity/${x.id}">View</a></div></div></div></article>`}
function listingGrid(rows=listings,compact=false){return `<div class="listing-grid ${compact?"compact":""}" id="listingGrid">${rows.length?rows.map(card).join(""):`<div class="empty"><h3>No matches yet</h3><p>Try a broader budget, category, or location.</p><button class="btn btn-soft" data-reset>Clear filters</button></div>`}</div>`}
function home(){return `<section class="hero"><div class="container"><div class="hero-grid"><div><div class="eyebrow">Business opportunities for Filipino MSMEs</div><h1>Find a business you can <em>start.</em></h1><p class="hero-copy">Explore negosyo packages, franchises, reseller opportunities, and expansion partners—with AI guidance and the FLAME PH network behind you.</p><div class="hero-actions"><a class="btn btn-primary" href="#/explore">Explore businesses <span>→</span></a><a class="btn btn-outline" href="#/find">Find my business match</a></div><form class="search-panel" id="homeSearch"><div class="search-input"><span>⌕</span><input name="q" placeholder="What business are you looking for?" aria-label="Search business opportunities"></div><select name="cap" aria-label="Maximum budget"><option value="">Any budget</option><option value="10000">Under ₱10K</option><option value="25000">Under ₱25K</option><option value="50000">Under ₱50K</option><option value="100000">Under ₱100K</option></select><button class="btn btn-primary">Search</button></form></div><div class="hero-art"><div class="hero-note">The FLAME PH Business Engine</div><div class="hero-photo"><img src="${photo("photo-1556761175-b413da4baf72",1100)}" alt="Filipino small business owners planning their next step"><div class="photo-label"><strong>Start local. Grow together.</strong><span>One ecosystem for your next move.</span></div></div><div class="float-card"><b>From idea to next branch</b><span>Opportunities · people · fulfillment</span></div></div></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="section-kicker">Start with what you have</div><h2>Explore by budget</h2></div><a class="link-arrow" href="#/explore">See all opportunities →</a></div><div class="budget-grid">${[["₱10K","Under ₱10,000",10000],["₱25K","Under ₱25,000",25000],["₱50K","Under ₱50,000",50000],["₱100K","Under ₱100,000",100000],["₱500K","Under ₱500,000",500000],["₱500K+","Above ₱500,000",500001]].map(a=>`<a class="budget-chip" href="#/explore?max=${a[2]}">${a[0]}<span>${a[1]}</span></a>`).join("")}</div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">Choose your path</div><h2>Popular negosyo categories</h2></div><a class="link-arrow" href="#/explore">Browse categories →</a></div><div class="category-grid">${cats.slice(0,6).map(c=>`<a class="category-card" href="#/explore?cat=${encodeURIComponent(c[1])}"><div class="category-icon">${c[0]}</div><strong>${c[1]}</strong><small>${c[2]}</small></a>`).join("")}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="section-kicker">Explore opportunities</div><h2>Ideas with room to grow</h2><p>Sample listings show how opportunities are presented. Review all terms and assumptions with each seller.</p></div><a class="link-arrow" href="#/explore">View marketplace →</a></div>${listingGrid(listings.slice(0,3))}</div></section><section class='section section-white home-capital-section'><div class='container'><div class='section-head'><div><div class='section-kicker'>Need capital to grow?</div><h2>Find funding assistance that fits your next move.</h2><p>Learn how to prepare your numbers, shortlist angels, venture funds, lenders, grants, and strategic partners, then send a thoughtful invitation.</p></div><a class='link-arrow' href='#/funder-finder'>Learn how Funder Finder works →</a></div><div class='feature-row'><article class='feature-card'><div class='category-icon'>₱</div><h3>Funder Finder guide</h3><p>Follow a practical path from funding need to pitch, diligence, and a respectful introduction.</p><a class='btn btn-soft' href='#/funder-finder?section=funder-steps'>Read the funding guide</a></article><article class='feature-card feature-card-accent'><div class='category-icon'>✦</div><h3>Build a pitch deck</h3><p>Turn your problem, solution, traction, market, economics, and capital ask into a clear investor story.</p><a class='btn btn-primary' href='#/funder-finder?section=pitch-deck'>Open the pitch-deck workshop</a></article></div></div></section><section class='section home-funder-section'><div class='container'><div class='section-head'><div><div class='section-kicker'>For investors and funders</div><h2>Showcase your funding offer to the right MSMEs.</h2><p>Publish your mandate, ticket range, preferred sectors, requirements, and offer type—from equity and co-ownership to inventory finance and credit.</p></div><a class='btn btn-outline' href='#/investor-funder'>Explore Investor/Funder offers</a></div><div class='trust-note'>Create an Investor/Funder account to prepare an offer draft and a branded mini landing page for review.</div></div></section><section class='section section-white'><div class='container'><div class='section-head'><div><div class='section-kicker'>Featured packages and franchise kits</div><h2>Explore opportunities built for your budget.</h2><p>Compare sample negosyo packages, franchise kits, reseller models, and equipment-led starts. Confirm the complete terms directly with each seller.</p></div><a class='link-arrow' href='#/explore?cat=Franchise'>Browse featured packages →</a></div>${listingGrid(listings.slice(3,6))}</div></section><section class="section section-white"><div class="container"><div class="match-band"><div><div class="section-kicker" style="color:#d8ec8a">Not sure where to start?</div><h2>Find the opportunity that fits your life.</h2><p>Tell us your budget, location, interests, and time. Get a shortlist to explore, with costs and tradeoffs clearly laid out.</p></div><a class="btn btn-white" href="#/find">Take the business finder →</a></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="section-kicker">More than a marketplace</div><h2>From finding a negosyo to fulfilling an order</h2></div></div><div class="steps">${[["01","Find an opportunity","Compare packages that fit your budget and goals."],["02","Talk to the seller","Ask questions and review the actual terms."],["03","Prepare to launch","Get training, supplier, and local support."],["04","Fulfill locally","Explore approved chapter and member providers."],["05","Grow your reach","Build a reseller network or plan your next market."]].map(s=>`<div class="step"><div class="step-num">${s[0]} / 05</div><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join("")}</div></div></section><section class="section section-white"><div class="container"><div class="quote-box"><strong>“A place to find the business, people, place, technology, and market that help your next step feel possible.”</strong><a class="btn btn-primary" href="#/ecosystem">Meet the FLAME PH ecosystem →</a></div></div></section>`}
function explore(query=""){let params=new URLSearchParams(query);let chosenCat=params.get("cat")||"";let max=params.get("max")||"";return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Explore businesses</div><div class="section-kicker">Negosyo marketplace</div><h1>Find your next business opportunity.</h1><p>Compare package prices, startup capital, operating models, and locations. Ask sellers for current terms and availability.</p></div></section><section class="section" style="padding-top:12px"><div class="container"><div class="content-grid"><aside class="filters"><h3>Refine results</h3><div class="filter-group"><strong>Maximum package price</strong>${[[10000,"Under ₱10,000"],[25000,"Under ₱25,000"],[50000,"Under ₱50,000"],[100000,"Under ₱100,000"],[500000,"Under ₱500,000"]].map(v=>`<label><input type="radio" name="budget-filter" value="${v[0]}" ${String(v[0])===max?"checked":""}> ${v[1]}</label>`).join("")}</div><div class="filter-group"><strong>Location</strong>${["NCR","Luzon","Visayas","Mindanao"].map(v=>`<label><input type="checkbox" name="region-filter" value="${v}"> ${v}</label>`).join("")}<label><input type="checkbox" name="region-filter" value="Nationwide"> Nationwide</label></div><div class="filter-group"><strong>Business model</strong>${["Home-based","Reseller","Store-based","Distribution","Mobile cart"].map(v=>`<label><input type="checkbox" name="model-filter" value="${v}"> ${v}</label>`).join("")}</div><button class="btn btn-soft" data-reset>Reset filters</button></aside><div><div class="toolbar"><input id="exploreQuery" placeholder="Search by business or keyword" value="${params.get("q")||""}"><select id="exploreCategory"><option value="">All categories</option>${cats.map(c=>`<option ${chosenCat===c[1]?"selected":""}>${c[1]}</option>`).join("")}</select><select id="exploreSort"><option value="recommended">Recommended</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><span class="count" id="resultCount">${listings.length} opportunities</span></div>${listingGrid(listings,true)}<p class="fine-print">Listings shown here are illustrative sample data. Availability, pricing, inclusions, and claims must be confirmed with the seller.</p></div></div></div></section>`}
function opportunity(id){let x=listings.find(y=>y.id===id)||listings[0];return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Explore / ${x.name}</div><span class="status-pill">Sample opportunity · Seller details reviewed</span><h1 style="margin-top:17px">${x.name}</h1><p>${x.desc}</p></div></section><section class="section" style="padding-top:10px"><div class="container two-col"><div><div class="listing-image" style="height:390px;border-radius:18px"><img src="${x.img}" alt="${x.cat} opportunity"></div><div class="panel" style="margin-top:16px"><h3>What's included</h3><ul>${x.includes.map(a=>`<li>${a}</li>`).join("")}</ul><div class="trust-note">Confirm the final package contents, fees, operating requirements, and contract directly with the seller before paying.</div></div><div class="panel" style="margin-top:16px"><h3>At a glance</h3><div class="table-wrap"><table><tbody><tr><td>Business type</td><td><strong>${x.cat}</strong></td></tr><tr><td>Operating model</td><td>${x.model}</td></tr><tr><td>Location</td><td>${x.city}, ${x.region}</td></tr><tr><td>Estimated startup capital</td><td>${x.capital}</td></tr><tr><td>Training</td><td>Ask seller for current details</td></tr></tbody></table></div></div></div><aside><div class="panel" style="position:sticky;top:95px"><div class="section-kicker">Seller supplied package price</div><div class="price-big">${money(x.price)}</div><p>Estimated total startup capital: <strong>${x.capital}</strong></p><span class="verified">✓ Seller profile review completed</span><p class="fine-print" style="margin-top:13px">Verification describes the checks completed; it does not guarantee profitability or investment returns.</p><button class="btn btn-primary" style="width:100%;margin:7px 0" data-inquire="${x.name}">Ask the seller a question</button><button class="btn btn-outline" style="width:100%" data-compare="${x.id}">Add to comparison</button><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><strong style="font-size:12px">Before you decide</strong><p style="font-size:12px;margin-top:8px">Request itemized fees, assumptions behind any estimates, sample contracts, support terms, and current territory availability.</p><button class="btn btn-soft" data-report="${x.name}">Report this listing</button></div></aside></div></div></section>`}
function finder(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Business finder</div><div class="section-kicker">A better place to begin</div><h1>What kind of negosyo fits you?</h1><p>Share a few preferences and see a sample shortlist from the opportunities currently shown on this site.</p></div></section><section class="section" style="padding-top:5px"><div class="container two-col"><form class="panel" id="finderForm"><h3>Tell us what works for you</h3><div class="form-grid"><div class="field"><label for="fBudget">Budget</label><select id="fBudget"><option value="25000">Up to ₱25,000</option><option value="50000">Up to ₱50,000</option><option value="100000">Up to ₱100,000</option><option value="500000">Up to ₱500,000</option><option value="1000000">₱500,000+</option></select></div><div class="field"><label for="fLocation">Where do you want to operate?</label><select id="fLocation"><option>Anywhere</option><option>NCR</option><option>Luzon</option><option>Visayas</option><option>Mindanao</option></select></div><div class="field"><label for="fModel">Preferred setup</label><select id="fModel"><option>Any model</option><option>Home-based</option><option>Store-based</option><option>Mobile cart</option><option>Reseller</option><option>Distribution</option></select></div><div class="field"><label for="fTime">Time available</label><select id="fTime"><option>Part-time</option><option>Full-time</option></select></div><div class="field full"><label for="fInterest">What interests you?</label><select id="fInterest"><option>Any category</option>${cats.map(c=>`<option>${c[1]}</option>`).join("")}</select></div><div class="field full"><button class="btn btn-primary">Show my matches →</button></div></div></form><div class="panel"><div class="section-kicker">A useful starting point</div><h3>Compare the total picture</h3><p>Package price is only one part of a business decision. Consider working capital, monthly expenses, location, time, suppliers, and support.</p><div class="notice">This demo matches only the sample listings visible on this website. It does not assess your finances or guarantee suitability.</div><a class="btn btn-outline" href="#/ai">Ask the NegosyoDepot AI Agent →</a></div><div id="finderResults" class="field full" style="grid-column:1/-1"></div></div></section>`}
function compare(){let ids=JSON.parse(localStorage.getItem("nd_compare")||"[]");let rows=listings.filter(x=>ids.includes(x.id));return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Compare</div><div class="section-kicker">Make an informed choice</div><h1>Compare business opportunities.</h1><p>Compare costs and operating needs side by side. Missing details should be requested from the seller.</p></div></section><section class="section" style="padding-top:10px"><div class="container" id="compareArea">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Opportunity</th>${rows.map(x=>`<th>${x.name}</th>`).join("")}</tr></thead><tbody>${[["Package price",x=>money(x.price)],["Estimated startup capital",x=>x.capital],["Category",x=>x.cat],["Operating model",x=>x.model],["Location",x=>x.city+", "+x.region],["Training/support",x=>"Confirm with seller"],["Space/staff requirements",x=>"Confirm with seller"],["Terms and recurring fees",x=>"Request itemized details"]].map(r=>`<tr><td><strong>${r[0]}</strong></td>${rows.map(x=>`<td>${r[1](x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div><div style="margin-top:16px">${rows.map(x=>`<button class="btn btn-outline" data-uncompare="${x.id}">Remove ${x.name}</button> `).join("")}<a class="btn btn-primary" href="#/explore">Add more opportunities</a></div>`:`<div class="panel"><h3>Your comparison is ready when you are.</h3><p>Choose Compare on any opportunity card. You can compare up to four sample opportunities in this demo.</p><a class="btn btn-primary" href="#/explore">Explore businesses →</a></div>`}<div class="trust-note" style="margin-top:20px">Estimated margins and payback periods are not displayed as verified facts. Ask sellers for assumptions and independently assess each opportunity.</div></div></section>`}
function grow(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Grow & expand</div><div class="section-kicker">From one location to the next</div><h1>Grow locally with the right partners around you.</h1><p>Turn a proven offer into a repeatable business model, recruit local partners, and find the operating support to serve new customers.</p></div></section><section class="section" style="padding-top:18px"><div class="container"><div class="two-col"><div class="panel"><div class="category-icon">📍</div><h3>Map your next territory</h3><p>Review seller-published locations and territory availability. Ask each brand to confirm current reservations and contract terms.</p><a class="btn btn-soft" href="#/explore">Browse opportunities by location →</a></div><div class="panel"><div class="category-icon">🤝</div><h3>Find resellers and distributors</h3><p>Package your offer, define partner requirements, and manage inquiries from potential resellers or local distributors.</p><a class="btn btn-outline" href="#/post">Prepare a business listing →</a></div></div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">The local growth loop</div><h2>Make expansion operational</h2></div></div><div class="steps">${[["01","Standardize","Clarify pricing, products, training, and service steps."],["02","Recruit","Find partners with a clear offer and expectations."],["03","Supply","Plan replenishment and approved fulfillment coverage."],["04","Support","Track onboarding, questions, and partner performance."],["05","Repeat","Expand when the model works in the next location."]].map(s=>`<div class="step"><div class="step-num">${s[0]}</div><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join("")}</div></div></section><section class="section"><div class="container banner"><div><h3>Local fulfillment can help you serve more neighborhoods.</h3><p>Explore FLAME PH chapter and member-operated providers, subject to approval and actual capacity.</p></div><a class="btn btn-primary" href="#/fulfillment">Explore fulfillment →</a></div></section>`}
function scale(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Scale globally</div><div class="section-kicker">Prepare before you cross borders</div><h1>Build a path from local strength to global opportunity.</h1><p>Global growth starts with repeatable operations, a distinctive offer, reliable supply, and a market worth testing.</p></div></section><section class="section" style="padding-top:16px"><div class="container two-col"><div class="panel"><h3>Readiness checklist</h3><ul><li>Document product quality and production capacity.</li><li>Understand packaging, labeling, and shelf-life needs.</li><li>Build export cost scenarios and realistic lead times.</li><li>Assess intellectual property and brand readiness.</li><li>Research target markets with current, authoritative sources.</li><li>Identify a qualified logistics and distribution partner.</li></ul></div><div class="panel"><h3>Use the AI Agent to organize your next steps</h3><p>Create a research checklist, draft distributor questions, or compare high-level scenarios using the information you provide.</p><div class="trust-note">Any market, customs, tax, certification, or legal requirements must be confirmed with qualified professionals and current official sources. This prototype does not provide export approval or live market data.</div><a class="btn btn-primary" style="margin-top:15px" href="#/ai">Plan my next step →</a></div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">A staged approach</div><h2>Expand with evidence</h2></div></div><div class="steps">${[["01","Prove locally","Document repeat demand and operating results."],["02","Standardize","Create reliable quality and partner processes."],["03","Select markets","Prioritize a few researched customer segments."],["04","Test channels","Run a limited distributor or export pilot."],["05","Scale carefully","Expand when the economics and operations hold."]].map(s=>`<div class="step"><div class="step-num">${s[0]}</div><h3>${s[1]}</h3><p>Build evidence before committing to a larger expansion.</p></div>`).join("")}</div></div></section>`}
const providers=[{n:"North Hub Micro-Fulfillment",loc:"Quezon City · NCR",services:"Receiving · storage · pick & pack",cap:"Small parcel and shelf-stable goods",status:"Illustrative provider"},{n:"Central Visayas Chapter Hub",loc:"Cebu City · Visayas",services:"Inventory · order prep · pickup handoff",cap:"Local MSME packages and replenishment",status:"Illustrative provider"},{n:"Bicol Chapter Fulfillment Point",loc:"Naga City · Luzon",services:"Package assembly · reseller replenishment",cap:"Small batch and neighborhood delivery",status:"Illustrative provider"},{n:"Davao Local Dispatch Hub",loc:"Davao City · Mindanao",services:"Receiving · pick & pack · carrier handoff",cap:"Dry goods and approved business packages",status:"Illustrative provider"}];
function fulfillment(){return `<section class="fulfillment-hero"><div class="container fulfillment-hero-grid"><div class="fulfillment-hero-copy"><div class="breadcrumbs">Home / FLAME PH fulfillment</div><div class="section-kicker">Fulfillment by MSMEs · powered by FLAME PH</div><h1>Local fulfillment that helps your negosyo move.</h1><p>Connect with chapter leaders and MSME members who can help receive, store, prepare, and hand off products near the customers you serve.</p><div class="hero-actions"><a class="btn btn-primary" href="#/fulfillment/providers">Find a local provider <span>→</span></a><button class="btn btn-outline" data-open-signup>Join the provider network</button></div><div class="fulfillment-proof"><span>For product-based MSMEs</span><span>Local operator network</span><span>Clear service terms</span></div></div><div class="fulfillment-hero-visual"><img src="${photo("photo-1586528116311-ad8dd3c8310d",1100)}" alt="Boxes moving through a small business fulfillment workspace"><div class="fulfillment-visual-card"><b>From stockroom to customer</b><span>Receive · Prepare · Dispatch</span></div><span class="fulfillment-orbit-dot">✦</span></div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">A network built around local capacity</div><h2>Practical help at each handoff.</h2><p>Choose the support that fits your operation. Agree on inventory, service levels, fees, and responsibilities before work begins.</p></div><a class="link-arrow" href="#/fulfillment/network">See how the network works →</a></div><div class="fulfillment-service-grid">${[["01","Receive & check","Document arrivals, quantities, condition, and exceptions."],["02","Store & organize","Plan suitable storage, stock visibility, and access rules."],["03","Pick & prepare","Set picking, packing, labeling, and quality-check steps."],["04","Dispatch & reconcile","Coordinate handoff, delivery records, returns, and service fees."]].map(x=>`<article class="fulfillment-service-card"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join("")}</div></div></section><section class="section"><div class="container fulfillment-model-grid"><div><div class="section-kicker">A fit for different stages</div><h2>Start with the help you need today.</h2><p>Some businesses need a few hours of packing support. Others need shared storage, scheduled dispatch, or a local operator for a new service area.</p><a class="btn btn-primary" href="#/fulfillment/cost-estimator">Plan a service request →</a></div><div class="fulfillment-model-list">${[["Shared micro-fulfillment","Flexible support for smaller, changing order volumes."],["Commissary & production support","Coordinate preparation, batching, and handoff for food and product MSMEs."],["Local distribution point","Use a suitable partner location to stage stock closer to customers."],["Merchant-managed fulfillment","Keep operations in-house and use the network for selected services."]].map(x=>`<a href="#/fulfillment/network"><strong>${x[0]}</strong><span>${x[1]}</span><b>Explore →</b></a>`).join("")}</div></div></section><section class="section section-white"><div class="container fulfillment-network-callout"><div><div class="section-kicker">For FLAME PH chapter leaders and members</div><h2>Turn local capability into a service MSMEs can use.</h2><p>Share your location, operating hours, equipment, coverage, and services. Network participation starts with an application and review.</p><a class="btn btn-primary" href="#/fulfillment/provider-register">Apply to become a provider →</a></div><div class="fulfillment-network-mark"><span>Local</span><b>→</b><span>Ready</span><b>→</b><span>Connected</span></div></div></section><section class="section"><div class="container"><div class="notice">Preview information: provider examples, coverage, prices, inventory capacity, and delivery availability must be confirmed. A service request is not a booking until the provider accepts written terms.</div><div class="section-head"><div><div class="section-kicker">Explore next</div><h2>Plan with confidence.</h2></div></div><div class="fulfillment-next-grid"><a href="#/fulfillment/providers"><strong>Find a provider</strong><span>Review location and service fit.</span>Browse the network →</a><a href="#/fulfillment/pricing"><strong>Understand costs</strong><span>See which costs to confirm.</span>Review pricing →</a><a href="#/fulfillment/guides"><strong>Prepare an operation</strong><span>Use practical checklists.</span>Open guides →</a></div></div></section>`}
const fulfillmentPageData={
"/fulfillment/start":["Start your fulfillment journey","A step-by-step introduction to local fulfillment support for Filipino product businesses.",["Choose the product and service area you want to support.","Estimate order volume, inventory needs, and handling steps.","Compare providers and confirm written service terms before onboarding."]],"/fulfillment/provider-register":["Register as a fulfillment provider","For FLAME PH chapter leaders and members ready to offer a defined logistics or operations service.",["Share your legal or member identity and primary contact.","Describe operating location, service area, hours, and capacity.","List equipment, safety practices, and services you can reliably deliver."]],"/fulfillment/provider-list":["List your facility or service","Create a clear provider profile that helps MSMEs assess location, fit, capabilities, and availability.",["Use accurate photos and a precise service-area description.","Separate confirmed capacity from seasonal or conditional availability.","State minimums, cut-off times, exclusions, and quote requirements."]],"/fulfillment/order-fulfillment":["Fulfill customer orders","Coordinate the handoffs from customer order to provider acceptance, preparation, dispatch, and reconciliation.",["Confirm order details and inventory ownership before work begins.","Record quantities, exceptions, packing requirements, and handoff evidence.","Reconcile agreed service fees, returns, and adjustments against the order."]],"/fulfillment/partner-onboarding":["Provider onboarding","A practical checklist for readiness review before a facility or operator is listed as available.",["Confirm identity, facility control, service scope, and operating contacts.","Review storage, sanitation, safety, access, and inventory procedures as applicable.","Agree on escalation contacts, service measures, and insurance or permits that may apply."]],"/fulfillment/incentives":["Member benefits and incentives","Learn how future FLAME PH network incentives may be communicated to participating providers.",["Only published, approved program terms define eligibility.","A referral or recruitment by itself does not promise earnings or rewards.","Any current incentive, amount, and payout timing must be verified before participation."]],"/fulfillment/pricing":["Fulfillment service pricing","Compare quotes by service scope and total cost, rather than looking at a single handling rate.",["Ask whether onboarding, receiving, storage, pick-and-pack, packaging, and dispatch are included.","Check minimum charges, volume tiers, taxes, deposits, and payment timing.","Get rate validity, service limits, and exception fees in writing."]],"/fulfillment/costs":["Compare fulfillment costs","A checklist to compare in-house work, a local MSME provider, and other delivery arrangements.",["Include labor, rent, utilities, supplies, technology, shrinkage, and returns.","Compare the same order profile and delivery service across options.","Keep one-time setup fees separate from recurring and per-order costs."]],"/fulfillment/cost-estimator":["Estimate order costs","Plan an indicative fulfillment budget using your own assumptions before requesting a provider quote.",["Enter average orders, units per order, storage days, and package size.","Separate known costs from estimates and unknown fees.","Use the result for planning only; provider quotations determine actual prices."]],"/fulfillment/optional-services":["Optional fulfillment services","Add only the services that solve a real operating need for your business.",["Packaging, labeling, kitting, and quality checks may require separate scope and pricing.","Returns handling, cold storage, and regulated goods need provider-specific confirmation.","Confirm materials, turnaround time, liability, and exception treatment in writing."]],"/fulfillment/quote-checklist":["What a fulfillment quote should include","A clear quote makes it easier to compare providers and avoid surprise charges.",["Service scope, assumptions, volume bands, and quote validity.","All set-up, recurring, per-unit, delivery, and exception charges.","Inventory responsibility, service targets, loss or damage process, and termination terms."]],"/fulfillment/brand-profile":["Create a brand profile","Help buyers and potential service partners understand your products, operating needs, and points of contact.",["Use consistent business and brand names with current contact details.","Describe products, pack sizes, handling needs, and intended service areas.","Separate verified documents from self-reported profile details."]],"/fulfillment/catalog":["Catalog and product readiness","Prepare product information that makes quoting, storage, and order handling more accurate.",["Document SKU, dimensions, weight, units per case, and barcode where available.","Describe shelf life, fragile handling, temperature, and storage constraints.","Keep product claims, labels, permits, and safety information current."]],"/fulfillment/brand-growth":["Grow your MSME brand","Build a consistent customer experience as you add products, channels, and fulfillment partners.",["Standardize packaging, product information, and service promises.","Track customer feedback, stock-outs, and order exceptions.","Expand into new areas only when supply, working capital, and support are ready."]],"/fulfillment/trust":["Product and seller checks","Understand what platform checks mean and what buyers and sellers still need to verify.",["A profile review is not a guarantee of product quality or business performance.","Confirm permits, labeling, authenticity, warranties, and written terms as appropriate.","Use report and support channels to document safety or service concerns."]],"/fulfillment/brand-protection":["Brand protection basics","Practical steps to protect your name, product information, and customer trust as you grow.",["Use consistent brand identifiers and keep ownership records organized.","Monitor unauthorized use and document concerns with dates and evidence.","Seek qualified advice for trademark, labeling, and intellectual-property questions."]],"/fulfillment/network":["How the local fulfillment network works","A service marketplace connects MSMEs that need operational support with participating local providers.",["Businesses describe products, order patterns, location, and service needs.","Providers share capabilities and confirm whether the request fits their capacity.","Both parties agree scope, fees, records, and responsibilities before fulfillment starts."]],"/fulfillment/self-fulfill":["Merchant-managed fulfillment","Keep your own operations and use an outside provider only for the steps that are useful to you.",["You remain responsible for your inventory, order promises, and customer communication.","A partner may support selected receiving, packing, storage, or dispatch tasks.","Write down custody, data sharing, handoff, and exception procedures."]],"/fulfillment/providers":["Find a local service provider","Explore provider profiles by location and required service, then request a quote to confirm fit.",["Check service area, opening hours, product restrictions, and current capacity.","Ask for a site review or operating references when appropriate.","Confirm quote and service agreement before sending stock or customer data."]],"/fulfillment/b2b":["Fulfillment for business-to-business orders","Coordinate larger cases, scheduled replenishment, and business customer handoffs.",["Agree order cut-offs, case quantities, delivery windows, and proof of receipt.","Plan account-specific pricing, documentation, and returns handling.","Coordinate stock availability and payment terms directly with the seller and buyer."]],"/fulfillment/global":["Prepare to reach new markets","Build the operations foundation for expansion beyond your current location.",["Standardize SKUs, packaging, traceability, and customer support.","Research local market access, customs, tax, product rules, and logistics independently.","Start with a pilot and measure service quality, landed cost, and cash-flow impact."]],"/fulfillment/marketing":["Promotion and market support","Prepare clear product stories and service information for online and offline sales channels.",["Use accurate product information, price, availability, and delivery expectations.","Plan promotions around inventory and fulfillment capacity.","Track campaign costs and outcomes using your own business records."]],"/fulfillment/academy":["FLAME PH MSME Academy","A practical learning hub for starting, operating, and expanding a small business.",["Learn basic costing, inventory, order handling, and customer service.","Use checklists to prepare products and facilities for partner operations.","Treat educational examples as guidance and validate decisions for your business."]],"/fulfillment/guides":["Fulfillment guides","Use simple operating checklists to define what happens at every handoff.",["Receiving checklist: expected units, condition, and discrepancy records.","Packing checklist: materials, labels, quality checks, and order accuracy.","Dispatch checklist: carrier handoff, tracking details, proof, and reconciliation."]],"/fulfillment/stories":["Stories from MSME operators","A place for real participating businesses to share lessons after consent and editorial review.",["No testimonial or result is implied until a real story is approved for publication.","Useful stories show context, constraints, process, and lessons learned.","Business outcomes vary and are not promised by a profile or program."]],"/fulfillment/blog":["MSME insights and articles","Practical notes on operations, selling, service design, and growth for Filipino MSMEs.",["Plan costs and capacity before accepting new order volume.","Build repeatable processes that a team or provider can follow.","Keep advice current and check any legal, tax, or regulatory details with qualified sources."]],"/fulfillment/online-selling":["Online selling basics","Prepare listings and order operations for a dependable online customer experience.",["Use complete photos, descriptions, price, stock, and delivery information.","Set realistic dispatch windows and a clear way to resolve issues.","Track fees, returns, customer questions, and cash settlement timing."]],"/fulfillment/export-readiness":["Export readiness","A starting point for assessing whether your product and operations can support international orders.",["Confirm export documentation, customs, taxes, destination rules, and restricted goods.","Calculate landed cost including packaging, insurance, duties, and returns.","Validate demand and partner capability with a small, carefully planned pilot."]]
};
function fulfillmentProviderPage(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">${link("/","Home")} / ${link("/fulfillment","Fulfillment by MSMEs")} / Find a provider</div><div class="section-kicker">Local operator directory</div><h1>Find a provider for the work you need done.</h1><p>Compare indicative service profiles, then confirm location, product fit, available capacity, full price, and terms directly before sending inventory.</p></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="notice">Illustrative demo profiles only. These are not verified operating facilities, current capacity, or confirmed service offers.</div><div class="listing-grid">${providers.map((x,i)=>`<article class="network-card"><div class="network-icon">${["⌂","▦","↗","⌁"][i%4]}</div><div><span class="status-pill">Demo profile</span><h3 style="margin-top:10px">${x.n}</h3><p>📍 ${x.loc}</p><p><strong>Services:</strong> ${x.services}</p><p><strong>Potential fit:</strong> ${x.cap}</p><button class="btn btn-soft" data-provider="${x.n}">Request a quote</button></div></article>`).join("")}</div><p class="fine-print" style="margin-top:18px">Provider inquiries are not bookings. Confirm written service terms, inventory ownership, pricing, liability, and operating schedule.</p></div></section>`}
function fulfillmentInfo(path){if(path==="/fulfillment/providers")return fulfillmentProviderPage();let d=fulfillmentPageData[path];if(!d)return infoPage(path);let estimator=path==="/fulfillment/cost-estimator"?`<section class="section section-white"><div class="container two-col"><form class="panel" id="fulfillmentEstimator"><div class="section-kicker">Your quote assumptions</div><h2 style="font-size:26px">Build an indicative monthly estimate.</h2><p>Enter the actual rates from a provider quote. Blank rates count as zero; no platform pricing is assumed.</p><div class="form-grid"><div class="field"><label for="estimateOrders">Orders per month</label><input id="estimateOrders" type="number" min="0" value="100" required></div><div class="field"><label for="estimateReceive">Receiving per order (₱)</label><input id="estimateReceive" type="number" min="0" step="0.01" value="0"></div><div class="field"><label for="estimateStorage">Storage per order (₱)</label><input id="estimateStorage" type="number" min="0" step="0.01" value="0"></div><div class="field"><label for="estimatePick">Pick and pack per order (₱)</label><input id="estimatePick" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label for="estimateDelivery">Delivery / dispatch per order (₱)</label><input id="estimateDelivery" type="number" min="0" step="0.01" value="0"></div></div></form><aside class="panel estimate-output"><span class="section-kicker">Indicative estimate only</span><strong id="estimateTotal">₱0.00</strong><p id="estimateBreakdown">Enter quote rates to estimate monthly service costs. Taxes, minimums, and exception charges are excluded.</p><a class="btn btn-primary" href="#/fulfillment/quote-checklist">Review quote checklist</a></aside></div></section>`:"";return `<section class="page-hero"><div class="container"><div class="breadcrumbs">${link("/","Home")} / ${link("/fulfillment","Fulfillment by MSMEs")} / ${d[0]}</div><div class="section-kicker">FLAME PH · MSME fulfillment</div><h1>${d[0]}</h1><p>${d[1]}</p><div class="hero-actions"><button class="btn btn-primary" data-open-signup>Get started with FLAME PH →</button><a class="btn btn-outline" href="#/fulfillment">Explore fulfillment</a></div></div></section><section class="section" style="padding-top:10px"><div class="container two-col"><article class="panel fulfillment-detail-panel"><div class="section-kicker">What to know</div><h2>Plan the next step clearly.</h2><ul>${d[2].map(x=>`<li>${x}</li>`).join("")}</ul><div class="notice">This is an informational preview. Confirm current program status, provider availability, price, and eligibility before making a business commitment.</div></article><aside class="panel fulfillment-next-panel"><span class="network-icon">✦</span><h3>Continue with local support</h3><p>Every service begins with a clear request, provider review, and written agreement.</p><a class="btn btn-soft" href="#/fulfillment/providers">Find a provider</a><a class="btn btn-outline" href="#/fulfillment/cost-estimator">Plan estimated costs</a><a class="btn btn-primary" href="#/fulfillment/provider-register">Join as a provider</a></aside></div></section>${estimator}<section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">Explore related topics</div><h2>Build a complete plan.</h2></div></div><div class="fulfillment-next-grid"><a href="#/fulfillment/guides"><strong>Operational guides</strong><span>Prepare a repeatable process.</span>Read the checklists →</a><a href="#/fulfillment/pricing"><strong>Costs and terms</strong><span>Ask for a complete written quote.</span>Review pricing →</a><a href="#/trust"><strong>Trust & safety</strong><span>Know what to verify before you commit.</span>See our guidance →</a></div></div></section>`}
function partners(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Corporate partners</div><div class="section-kicker">Corporate Partner Program</div><h1>Grow your network through real business opportunities.</h1><p>Present approved negosyo packages to qualified buyers and manage partner referrals, sales, payment records, and fulfillment in one place.</p><a href="#/login" class="btn btn-primary">Apply for a Corporate Partner account →</a></div></section><section class="section" style="padding-top:15px"><div class="container two-col"><div class="panel"><h3>For corporate partners</h3><ul><li>Publish package variants and branch availability.</li><li>Invite referral members and create trackable links.</li><li>Review attributed inquiries, orders, and confirmed pay-ins.</li><li>Monitor fulfillment status and branch performance.</li><li>Download transaction-level statements.</li></ul></div><div class="panel"><h3>For referral members</h3><ul><li>Share approved opportunities using a referral link.</li><li>Follow lead progress with clear attribution.</li><li>See eligible earnings and their calculation basis.</li><li>Track held, available, paid, and adjusted balances.</li><li>Review a transaction statement at any time.</li></ul><div class="trust-note">Any commission plan must be approved and displayed before activation. Earnings are tied to eligible customer transactions; recruiting alone does not create commissions.</div></div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">Clear financial records</div><h2>Know what was paid, earned, and settled</h2></div></div><div class="steps">${[["01","Attribute","A consented referral code is connected to an eligible order."],["02","Confirm","Customer pay-ins are independently confirmed."],["03","Calculate","The saved plan version determines each commission."],["04","Review","Holds, refunds, adjustments, and overrides are visible."],["05","Settle","Payouts follow the approved release and reconciliation process."]].map(s=>`<div class="step"><div class="step-num">${s[0]}</div><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join("")}</div></div></section>`}
function membership(){let tiers=[["FLAME APPRENTICE",0,0,3,"Start and explore"],["FLAME STARTER",30,300,6,"Get discovered"],["FLAME MICRO",60,600,10,"Start selling"],["FLAME NEO",120,1200,25,"Get more leads"],["FLAME PRO",360,3600,50,"Recruit partners"],["FLAME CHAMPION",720,7200,100,"Scale nationwide"]];return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Membership</div><div class="section-kicker">FLAME PH membership</div><h1>Start free. Grow when you're ready.</h1><p>Choose a membership that fits your current business stage. Browse opportunities without a paid plan.</p></div></section><section class="section" style="padding-top:16px"><div class="container"><div class="tier-grid">${tiers.map((t,i)=>`<article class="tier-card ${i===0?"featured":""}"><div class="tier-label">${t[0]}</div><div class="tier-price">${money(t[1])}<small> / month</small></div><div style="font-size:12px;color:var(--muted)">${money(t[2])} billed annually</div><ul><li>${t[3]} active listings</li><li>Browse opportunities</li><li>${t[4]}</li><li>Member profile and ecosystem access</li></ul><a class="btn ${i===0?"btn-primary":"btn-outline"}" style="width:100%" href="#/login">${i===0?"Join for free":"Choose this tier"}</a></article>`).join("")}</div><p class="fine-print" style="margin-top:17px">Pricing and listing allowances are the supplied plan configuration. Paid checkout and membership entitlements require live account and payment integration. Higher Champion listing limits may be configurable.</p></div></section>`}
function ai(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / FLAME AI</div><div class="section-kicker">Business guidance from FLAME PH</div><h1>Continue to FLAME AI</h1><p>Open FLAME AI on flameph.org for business guidance and support.</p><a class="btn btn-primary" href="https://flameph.org/bizconsult-ai" target="_blank" rel="noopener noreferrer">Open FLAME AI →</a><p class="fine-print">FLAME AI is provided on the FLAME PH website. NegosyoDepot does not provide AI responses on this page.</p></div></section>`}
function login(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / FLAMEPH account</div><div class="section-kicker">One FLAMEPH Member ID</div><h1>Join the ecosystem. Start free.</h1><p>Use one account across FLAMEPH, MarketplacePH, and NegosyoDepot.</p></div></section><section class="section" style="padding-top:5px"><div class="container two-col"><div class="panel"><h3>Create your free FLAMEPH account</h3><p>Start free with FLAME APPRENTICE. No payment card required.</p><a class="btn btn-outline" style="width:100%;margin:6px 0" href="https://www.flameph.org/join" target="_blank" rel="noopener noreferrer">Create your FLAME PH account</a><a class="link-arrow" href="#/dashboard">Already created an account? Set up your NegosyoDepot workspace preview →</a><div class="section-kicker" style="text-align:center;margin:14px">or continue with</div><form id="signupForm"><div class="option-row" style="margin-bottom:15px"><button type="button" class="option-pill active" data-auth-mode="email">Email</button><button type="button" class="option-pill" data-auth-mode="mobile">Mobile number</button></div><div class="field"><label id="authLabel" for="authInput">Email address</label><input id="authInput" name="identity" type="email" placeholder="you@example.com" required><small id="authHelp">We’ll send a one-time sign-in code.</small></div><input type="hidden" id="authInvite" name="invite"><label class="check-row" style="margin:14px 0"><input type="checkbox" required><span>I agree to the <a href="#/terms"><u>Terms</u></a> and <a href="#/privacy"><u>Privacy Notice</u></a>.</span></label><label class="check-row" style="margin:13px 0"><input type="checkbox" name="updates"><span>Send me platform updates and new-feature announcements. (Optional)</span></label><button class="btn btn-primary" style="width:100%">Continue securely</button></form><p class="fine-print" style="margin-top:15px">Email and mobile sign-in inside NegosyoDepot are not connected. Create or access your FLAME PH member account using the account link above.</p></div><div class="panel"><div class="category-icon">✦</div><h3>Your membership starts free</h3><div class="price-big">₱0</div><p>FLAME APPRENTICE includes up to 3 active NegosyoDepot listings.</p><ul><li>Keep one permanent FLAMEPH Member ID.</li><li>Explore business opportunities and local support.</li><li>Move across ecosystem platforms with your account.</li><li>Add profile details only when you need them.</li></ul><div class="notice">A member ID identifies your account. It does not grant admin, founder, chapter, partner, or payout access.</div></div></div></section>`}
function post(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / Post a business</div><div class="section-kicker">For MSME owners and brands</div><h1>Put your negosyo in front of future partners.</h1><p>Create a clear package listing for entrepreneurs, resellers, dealers, and distributors.</p></div></section><section class="section" style="padding-top:12px"><div class="container two-col"><form class="panel" id="postForm"><h3>Start your listing</h3><div class="form-grid"><div class="field full"><label>Business or package name</label><input required placeholder="e.g. Neighborhood coffee cart"></div><div class="field"><label>Opportunity type</label><select><option>Negosyo package</option><option>Reseller</option><option>Distributor</option><option>Franchise</option><option>Equipment + business</option></select></div><div class="field"><label>Starting package price (₱)</label><input type="number" min="0" placeholder="25000"></div><div class="field"><label>Estimated total startup capital</label><input placeholder="e.g. ₱25,000–₱50,000"></div><div class="field"><label>Location / service area</label><input placeholder="City, province, or nationwide"></div><div class="field full"><label>What does the package include?</label><textarea rows="4" placeholder="Be specific about equipment, training, support, and recurring fees"></textarea></div><div class="field full"><button class="btn btn-primary">Save listing draft</button><small>Draft saving and publishing require member sign-in and seller verification.</small></div></div></form><div class="panel"><h3>Make the offer clear</h3><p>Entrepreneurs need to understand the full startup picture and decide what to ask next.</p><ul><li>Show package price and startup capital separately.</li><li>List recurring and optional costs.</li><li>Explain training and supplier support.</li><li>State location and territory availability.</li><li>Include assumptions for any financial estimates.</li></ul><div class="trust-note">“Post free” means no extra listing charge within your membership allowance. Membership charges and benefits are shown separately.</div></div></div></section>`}
const profileKey="nd_member_profile_v1";
function readMemberProfile(){try{return JSON.parse(localStorage.getItem(profileKey)||"{}")||{}}catch{return {}}}
function profileCompletion(p){const keys=["displayName","memberType","industry","location","businessStage","goal","offering","seeking"];return Math.round(keys.filter(k=>String(p[k]||"").trim()).length/keys.length*100)}
function dashboard(){const p=readMemberProfile(),savedCount=saved().length,compareCount=compared().length,lookingCount=(()=>{try{return JSON.parse(localStorage.getItem("nd_looking_for")||"[]").length}catch{return 0}})(),pct=profileCompletion(p),goal=p.goal||"Choose a business goal";return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / My workspace</div><div class="section-kicker">Your NegosyoDepot workspace</div><h1>Your next business move starts here.</h1><p>Set a goal, improve your profile, and keep your opportunity shortlist together.</p><div class="hero-actions"><a class="btn btn-primary" href="#/profile">${p.displayName?"Update my profile":"Build my profile"}</a><a class="btn btn-outline" href="#/install">Add to Home Screen</a></div></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="dashboard-shell"><aside class="dash-side"><strong>Workspace</strong><a class="active" href="#/dashboard">Overview</a><a href="#/profile">My profile</a><a href="#/compare">Saved & compare</a><a href="#/looking-for">Requests</a><a href="#/post">My listings</a><a href="#/partners">Partners</a><a href="#/fulfillment">Fulfillment</a><a href="#/fulfillment/academy">Learn & grow</a><a href="#/install">Add to Home Screen</a></aside><div class="dash-main"><div class="workspace-welcome"><div><span class="section-kicker">${p.displayName?`Welcome, ${esc(p.displayName)}`:"Welcome to your workspace"}</span><h2>${esc(goal)}</h2><p>Choose the next step that fits your business today.</p></div><span class="status-pill">Saved on this device</span></div><div class="metric-grid">${[["Saved opportunities",savedCount,"#/compare"],["Compared",compareCount,"#/compare"],["Request drafts",lookingCount,"#/looking-for"],["Profile complete",`${pct}%`,"#/profile"]].map(m=>`<a class="metric workspace-metric" href="${m[2]}"><small>${m[0]}</small><strong>${m[1]}</strong></a>`).join("")}</div><div class="profile-progress-card"><div class="section-head"><div><div class="section-kicker">Your member profile</div><h3>${pct===100?"Your profile is ready for review":"Help the right people understand your business"}</h3></div><strong>${pct}%</strong></div><div class="progress-track" role="progressbar" aria-label="Profile completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div><p>${p.displayName?"Add the details that help potential customers, suppliers, partners, and funders assess fit.":"A clear profile can make future introductions more useful. Add only information you are comfortable sharing."}</p><a class="btn btn-soft" href="#/profile">${pct?"Continue profile":"Start profile"} →</a><small class="fine-print">This preview stores your profile in this browser only. It does not sync to other devices and may be removed when browser data is cleared. Do not enter confidential information.</small></div><div class="workspace-next-grid"><article class="panel"><span class="category-icon">⌕</span><h3>Explore a good fit</h3><p>Compare sample opportunities by budget, category, and location. Confirm all current terms with the provider.</p><a class="btn btn-soft" href="#/find">Use Business Finder</a></article><article class="panel"><span class="category-icon">＋</span><h3>Describe what you need</h3><p>Prepare a private request draft for a supplier, partner, service, funder, or fulfillment provider.</p><a class="btn btn-outline" href="#/looking-for">Create a request</a></article><article class="panel"><span class="category-icon">▦</span><h3>Build business readiness</h3><p>Work through practical guidance for your brand, operations, fulfillment, and future markets.</p><a class="btn btn-outline" href="#/fulfillment/academy">Browse learning</a></article></div><div class="install-prompt-card"><div><strong>Keep NegosyoDepot close at hand</strong><p>Add the website to your phone or desktop for a quicker way back to your workspace.</p></div><a class="btn btn-primary" href="#/install">Add to Home Screen</a></div><div class="notice">Sign-in, public profiles, shared requests, listings, messages, notifications, payments, and membership data need a connected account and backend. This workspace preview does not create or publish those records.</div></div></div></div></section>`}
function memberProfilePage(){const p=readMemberProfile();const options=(items,value)=>items.map(x=>`<option ${x===value?"selected":""}>${esc(x)}</option>`).join("");return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/dashboard">Workspace</a> / My profile</div><div class="section-kicker">A clear profile helps others assess fit</div><h1>Tell people what your business does.</h1><p>Prepare a profile with the details that help customers, suppliers, local partners, and funders understand your goals.</p><span class="status-pill">Private device preview · Not published</span></div></section><section class="section" style="padding-top:12px"><div class="container profile-layout"><form class="panel profile-form" id="memberProfileForm"><div class="section-head"><div><div class="section-kicker">Profile details</div><h2>Start with the essentials</h2></div><strong id="profileCompletionLabel">${profileCompletion(p)}%</strong></div><div class="progress-track" role="progressbar" aria-label="Profile completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${profileCompletion(p)}"><span id="profileProgressBar" style="width:${profileCompletion(p)}%"></span></div><div class="form-grid"><div class="field"><label for="profileName">Your name or public contact name</label><input id="profileName" name="displayName" maxlength="80" autocomplete="name" value="${esc(p.displayName||"")}" placeholder="How should other members address you?"></div><div class="field"><label for="profileType">I am here as</label><select id="profileType" name="memberType">${options(["","Aspiring entrepreneur","MSME owner","Supplier or service provider","Investor or funder","Business partner","Fulfillment provider"],p.memberType||"")}</select></div><div class="field"><label for="profileBusiness">Business or organization name</label><input id="profileBusiness" name="businessName" maxlength="100" value="${esc(p.businessName||"")}" placeholder="Optional for aspiring entrepreneurs"></div><div class="field"><label for="profileIndustry">Industry or business category</label><input id="profileIndustry" name="industry" maxlength="80" value="${esc(p.industry||"")}" placeholder="e.g. Food, retail, agriculture"></div><div class="field"><label for="profileLocation">Base location</label><input id="profileLocation" name="location" maxlength="100" autocomplete="address-level2" value="${esc(p.location||"")}" placeholder="City or municipality, province"></div><div class="field"><label for="profileStage">Business stage</label><select id="profileStage" name="businessStage">${options(["","Exploring an idea","Preparing to launch","Operating under 1 year","Operating 1–5 years","Operating 5+ years","Expanding to new markets"],p.businessStage||"")}</select></div><div class="field full"><label for="profileAbout">Short introduction</label><textarea id="profileAbout" name="about" rows="3" maxlength="500" placeholder="What do you do, who do you serve, and what makes your approach useful?">${esc(p.about||"")}</textarea><small>Keep it factual. Leave out confidential financial, customer, and identity details.</small></div><div class="field full"><label for="profileOffering">What can you offer?</label><textarea id="profileOffering" name="offering" rows="2" maxlength="300" placeholder="Products, services, skills, supply capacity, or experience">${esc(p.offering||"")}</textarea></div><div class="field full"><label for="profileSeeking">What are you looking for?</label><textarea id="profileSeeking" name="seeking" rows="2" maxlength="300" placeholder="Customers, suppliers, a distributor, advice, funding, or a partner">${esc(p.seeking||"")}</textarea></div><div class="field"><label for="profileGoal">Your main goal</label><select id="profileGoal" name="goal">${options(["","Start a business","Grow local sales","Find suppliers or services","Find a partner or distributor","Prepare for funding","Expand to new markets"],p.goal||"")}</select></div><div class="field"><label for="profileContact">Preferred contact approach</label><select id="profileContact" name="contactPreference">${options(["Platform messages when available","Share business contact after an introduction","Keep contact private until we agree"],p.contactPreference||"Keep contact private until we agree")}</select></div><div class="field full"><label for="profilePhotoNote">Profile image</label><div class="photo-placeholder"><span aria-hidden="true">${esc((p.displayName||p.businessName||"N").trim().slice(0,1).toUpperCase())}</span><p>Image upload will be available with secure member storage. For now, this preview uses an initials mark and does not accept external image URLs.</p></div></div></div><label class="check-row"><input id="profileConsent" type="checkbox" ${p.profileConsent?"checked":""}><span>I understand this profile is saved only on this device and is not visible to other members.</span></label><button class="btn btn-primary" type="submit">Save profile on this device</button><p class="fine-print" id="profileSaveStatus" role="status">Your profile is private and local to this browser.</p></form><aside class="profile-preview panel"><div class="section-kicker">Preview</div><div class="profile-avatar" id="profileAvatar">${esc((p.displayName||p.businessName||"N").trim().slice(0,1).toUpperCase())}</div><span class="status-pill">Not verified · Not published</span><h2 id="profilePreviewName">${esc(p.displayName||"Your name")}</h2><h3 id="profilePreviewBusiness">${esc(p.businessName||p.memberType||"Your business or role")}</h3><p id="profilePreviewAbout">${esc(p.about||"Add a short introduction so people can understand what you do.")}</p><div class="profile-preview-meta"><span id="profilePreviewIndustry">${esc(p.industry||"Industry")}</span><span id="profilePreviewLocation">${esc(p.location||"Location")}</span><span id="profilePreviewStage">${esc(p.businessStage||"Business stage")}</span></div><hr><strong>Can offer</strong><p id="profilePreviewOffering">${esc(p.offering||"Add products, services, capacity, or experience.")}</p><strong>Looking for</strong><p id="profilePreviewSeeking">${esc(p.seeking||"Describe the connection that would help you grow.")}</p><div class="notice">This is a private preview. Publishing, contact controls, profile search, and verification become available after account and moderation services are connected.</div></aside></div></section>`}
function installPage(){return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / Add to Home Screen</div><div class="section-kicker">A quicker way back to your business workspace</div><h1>Add NegosyoDepot to your device.</h1><p>Use your browser’s install option to add a launcher. The site still needs an internet connection for current content and member services.</p><button class="btn btn-primary" id="installAppButton" type="button" hidden>Add to Home Screen</button><p class="fine-print" id="installStatus" role="status"></p></div></section><section class="section"><div class="container install-guide-grid"><article class="panel install-guide" id="installAndroid"><div class="section-kicker">Android</div><h2>Chrome or Edge</h2><ol><li>Open negosyodepot.com in Chrome or Edge.</li><li>Tap the browser menu (⋮).</li><li>Choose <strong>Install app</strong> or <strong>Add to Home screen</strong>, then confirm.</li></ol></article><article class="panel install-guide" id="installIos"><div class="section-kicker">iPhone and iPad</div><h2>Safari</h2><ol><li>Open negosyodepot.com in Safari.</li><li>Tap the Share button (the square with an up arrow).</li><li>Scroll and tap <strong>Add to Home Screen</strong>, then tap Add.</li></ol><p class="fine-print">The browser controls this action; the website cannot display Apple’s install dialog itself.</p></article><article class="panel install-guide" id="installDesktop"><div class="section-kicker">Desktop</div><h2>Chrome, Edge, or Safari</h2><ol><li>Open negosyodepot.com in your browser.</li><li>Chrome or Edge: choose the install icon in the address bar, or use the browser menu’s install option.</li><li>Safari on Mac: use File → Add to Dock where available.</li></ol></article></div><div class="container"><div class="notice" style="margin-top:20px">Adding a launcher does not install a separate native app. It opens the website. The service worker caches the basic interface only. Device-local preview drafts may still appear offline in this browser, but they do not sync to other devices.</div></div></section>`}
function sellBusinessPage(){const steps=[["Set your goals and boundaries","Decide whether you are selling shares, assets, a location, or an operating business. Set timing, transition expectations, confidentiality needs, and acceptable deal structure."],["Prepare clean records","Organize financial statements, tax filings, inventory, contracts, leases, licenses, staff obligations, supplier terms, and equipment records. Explain unusual or one-time items."],["Establish a defensible value range","Use documented earnings, assets, and business risks. Ask qualified independent valuation, accounting, and legal professionals for advice; an asking price is not an appraisal."],["Make the business buyer-ready","Document operations, included assets, IP ownership, customer concentration, recurring obligations, and transition needs. Separate verified facts from estimates."],["Create a clear confidential listing","Summarize the business, location, asking range, included assets, and performance context. Keep sensitive identifiers and customer data out of public materials."],["Qualify buyers and share safely","Confirm buyer identity, experience, funding readiness, and intent. Consult counsel about confidentiality terms before sharing sensitive records."],["Negotiate, verify, and close","Get written terms and professional help with taxes, permits, employees, liabilities, transfer approvals, closing documents, and a realistic handover."]];return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / Sell Business</div><div class="section-kicker">For MSME owners ready for their next chapter</div><h1>Sell your business with clarity.</h1><p>A practical path from organizing your records to finding a qualified buyer and planning a responsible handover.</p><div class="hero-actions"><a class="btn btn-primary" href="#/post" data-open-signup>Prepare a sale listing</a><a class="btn btn-outline" href="#/funder-finder">Explore funding options</a></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="section-kicker">A measured, buyer-ready process</div><h2>Steps to sell your business</h2></div><p>Verify information and get independent professional advice before agreeing to a sale.</p></div><div class="guide-step-grid">${steps.map((x,i)=>`<article class="guide-step"><span class="guide-step-number">${String(i+1).padStart(2,"0")}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join("")}</div></div></section><section class="section section-white"><div class="container two-col"><article class="panel"><div class="section-kicker">Before you publish</div><h2 style="font-size:28px">Sale preparation checklist</h2><ul class="guide-checklist"><li>Financial statements and tax records</li><li>Asset, inventory, contract, and license list</li><li>Documented operating procedures and transition needs</li><li>Clear inclusions, exclusions, and asking range</li><li>Buyer qualification and confidentiality process</li><li>Independent accounting, legal, and tax support</li></ul></article><aside class="panel guide-callout"><span class="section-kicker">Protect your next step</span><h3>Keep sensitive records private.</h3><p>Do not publish bank details, customer information, employee records, passwords, or unredacted contracts. Share sensitive materials only after verifying the buyer and arranging a secure process.</p><a class="btn btn-soft" href="#/trust">Read trust & safety guidance</a></aside></div></section><section class="section"><div class="container banner"><div><h3>Ready to prepare your sale?</h3><p>Start a draft and have your information reviewed before publishing.</p></div><a class="btn btn-primary" href="#/post" data-open-signup>Start a listing draft →</a></div><p class="fine-print" style="margin-top:14px">Educational guidance only; not legal, tax, brokerage, or valuation advice. No buyer, sale price, financing, or transaction outcome is guaranteed.</p></section>`}
function funderFinderPage(){const steps=[["Choose the right kind of capital","Match your need and stage to angel equity, venture capital, repayable finance, eligible grants, or strategic commercial partners."],["Build a funder-fit shortlist","Check each funder’s sector, geography, stage, check size, thesis, eligibility, and recent activity on official channels. Avoid unverified paid-access intermediaries."],["Prepare credible materials","Create a concise deck, financial model, ownership summary, traction evidence, and secure data room. Label assumptions, cite sources, and reconcile every figure."],["Ask for a warm introduction","Request an introduction from a trusted founder, adviser, chapter leader, customer, or investor. Provide a brief forwardable note and ask permission before sharing contact details."],["Send a tailored invitation","Explain why this funder fits, what your business does, your evidence, the amount sought, and the next conversation you request."],["Follow up thoughtfully","Track outreach, share only requested material securely, follow up once after a reasonable interval, and respect a no or no-response. Do not mass-spam."],["Verify terms before closing","Confirm identity and authority. Review valuation, fees, interest, security, dilution, control rights, repayment, and conditions with independent professionals."]];return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / Funder Finder</div><div class="section-kicker">Capital readiness for Philippine MSMEs</div><h1>Find the right funder for your next move.</h1><p>Prepare your business, identify a capital source that fits, and invite potential backers with a clear and credible case.</p><div class="hero-actions"><a class="btn btn-primary" href="#/funder-finder?section=pitch-deck">Build your pitch deck</a><a class="btn btn-outline" href="#/funder-finder?section=funder-steps">Review the outreach guide</a></div></div></section><section class="section section-white" id="funder-steps"><div class="container"><div class="section-head"><div><div class="section-kicker">Angels · VCs · lenders · grants · strategic partners</div><h2>A respectful path to funding</h2></div><p>A preparation guide; it does not represent funders or promise introductions or investment.</p></div><div class="guide-step-grid">${steps.map((x,i)=>`<article class="guide-step"><span class="guide-step-number">${String(i+1).padStart(2,"0")}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join("")}</div></div></section><section class="section" id="pitch-deck"><div class="container"><div class="section-head"><div><div class="section-kicker">Pitch deck workshop</div><h2>Build a focused investor story.</h2></div><p>Draft an evidence-led narrative, then tailor the deck to the funder’s focus.</p></div><div class="pitch-layout"><article class="panel pitch-guide"><h3>Suggested slide sequence</h3><ol><li>Opening, one-line promise, and capital purpose</li><li>Customer problem and evidence</li><li>Solution, product, and differentiation</li><li>Defined market and credible sources</li><li>Business model, pricing, and unit economics</li><li>Verified traction and customer proof</li><li>Go-to-market and distribution plan</li><li>Competition and defensibility</li><li>Team, operations, and execution gaps</li><li>Financial outlook, assumptions, and risks</li><li>Capital ask, use of funds, runway, and milestones</li></ol><p class="fine-print">Do not present projections as actual results. Cite sources and dates for market claims.</p></article><form class="panel pitch-builder" id="pitchDeckBuilder"><h3>Draft your one-page pitch</h3><p>Saved only in this browser on this device. Nothing is uploaded.</p><div class="field"><label for="pitchBusiness">Business and one-line description</label><textarea id="pitchBusiness" rows="2" required placeholder="What do you do, and for whom?"></textarea></div><div class="field"><label for="pitchProblem">Customer problem and evidence</label><textarea id="pitchProblem" rows="2" required></textarea></div><div class="field"><label for="pitchSolution">Solution and advantage</label><textarea id="pitchSolution" rows="2" required></textarea></div><div class="field"><label for="pitchTraction">Traction or validation</label><textarea id="pitchTraction" rows="2" placeholder="Verified metrics, pilots, repeat orders, or feedback"></textarea></div><div class="field"><label for="pitchMarket">Target market and go-to-market</label><textarea id="pitchMarket" rows="2" required></textarea></div><div class="field"><label for="pitchAsk">Capital sought and use of funds</label><textarea id="pitchAsk" rows="2" required></textarea></div><button class="btn btn-primary" type="submit">Save and create pitch outline</button><div id="pitchOutputWrap" class="pitch-output-wrap" hidden><label for="pitchOutput">Your copyable pitch outline</label><textarea id="pitchOutput" rows="12" readonly></textarea><button class="btn btn-outline" type="button" data-copy-pitch>Copy outline</button><span class="fine-print" id="pitchSaveStatus" role="status"></span></div></form></div></div></section><section class="section section-white"><div class="container banner"><div><h3>Make each introduction specific.</h3><p>Tailor every invitation to the funder’s published focus, stage, and geography.</p></div><a class="btn btn-primary" href="#/funder-finder?section=pitch-deck">Continue your pitch draft →</a></div></section>`}
function bindFundingTools(){const form=document.getElementById("pitchDeckBuilder");if(!form)return;const fields=["pitchBusiness","pitchProblem","pitchSolution","pitchTraction","pitchMarket","pitchAsk"],labels=["Business","Customer problem and evidence","Solution and advantage","Traction or validation","Target market and go-to-market","Capital sought and use of funds"];function output(){document.getElementById("pitchOutput").value=`NEGOSYODEPOT · FUNDING PITCH DRAFT\n\n${fields.map((id,i)=>`${labels[i]}\n${document.getElementById(id).value.trim()||"[Add details]"}`).join("\n\n")}\n\nAdd verified details for financials, team, competition, and milestones before sharing.`;document.getElementById("pitchOutputWrap").hidden=false}try{const saved=JSON.parse(localStorage.getItem("nd_pitch_deck_draft")||"{}");fields.forEach(id=>{if(saved[id])document.getElementById(id).value=saved[id]});if(saved.pitchBusiness)output()}catch{}form.addEventListener("submit",e=>{e.preventDefault();const saved=Object.fromEntries(fields.map(id=>[id,document.getElementById(id).value.trim()]));try{localStorage.setItem("nd_pitch_deck_draft",JSON.stringify(saved));document.getElementById("pitchSaveStatus").textContent="Saved on this device."}catch{document.getElementById("pitchSaveStatus").textContent="Storage unavailable; copy the outline before leaving."}output()});document.querySelector("[data-copy-pitch]")?.addEventListener("click",async()=>{const box=document.getElementById("pitchOutput");try{await navigator.clipboard.writeText(box.value);document.getElementById("pitchSaveStatus").textContent="Copied to clipboard."}catch{box.focus();box.select();document.getElementById("pitchSaveStatus").textContent="Select and copy the outline."}})}
function infoPage(path){const pages={"/resources":["Resources for your next business step","Practical starting points for evaluating a package, preparing to launch, and planning your next market.",[["Opportunity checklist","Review total startup capital, ongoing expenses, seller support, training, and contract terms."],["Seller conversation guide","Ask what is included, what is recurring, and how territory availability is confirmed."],["Expansion readiness","Standardize the offer, supply, service quality, and partner onboarding before repeating."],["Fulfillment basics","Clarify receiving, inventory ownership, fees, capacity, and delivery handoff."]]],"/ecosystem":["One ecosystem. Five engines working together.","FLAME PH helps aspiring entrepreneurs and MSMEs connect the people, businesses, assets, technology, and markets needed to grow.",[["FLAME PH · People","Community, chapter networks, and entrepreneurial learning."],["NegosyoDepot · Business","Business packages, franchises, suppliers, and growth opportunities."],["Asset Engine · Place","Locations, equipment, commissaries, and warehouses."],["Digital Engine · Technology","Digital tools, AI, and operating systems."],["Growth Engine · Market","Customers, marketing, distribution, and expansion."]]],"/trust":["Trust starts with clear information.","Business opportunities involve meaningful decisions. NegosyoDepot helps organize discovery and due diligence.",[["Understand verification","A badge describes identity or documents reviewed under a stated process. It is not a guarantee of profitability."],["Review package terms","Request itemized costs, assumptions, service obligations, and written agreements."],["Report concerns","Use report controls on a listing or ask support for help documenting a concern."],["Use your judgment","Confirm seller claims and seek independent advice appropriate to your decision."]]],"/privacy":["Privacy overview","This page is a draft overview for the NegosyoDepot product. Replace it with the approved FLAME PH privacy notice before collecting real user data.",[["Account data","The planned service uses a FLAMEPH Member ID and verified sign-in method."],["Marketplace activity","Saved items and inquiries should be used to provide requested platform services."],["Optional updates","Marketing updates require separate opt-in and must be easy to withdraw."],["Your choices","Users should be able to request access, correction, and account help through support."]]],"/terms":["Platform terms overview","Draft content only. Have the approved platform terms reviewed and published before accepting real users or processing orders.",[["Marketplace role","NegosyoDepot provides tools for opportunity discovery and seller inquiries."],["Seller responsibility","Sellers are responsible for accurate listings, terms, availability, and representations."],["Due diligence","Buyers should verify details and review written agreements before payment."],["No guaranteed outcome","Listing information does not guarantee business success, revenue, or returns."]]],"/contact":["Talk to the NegosyoDepot team","Tell us whether you are exploring a business, listing an opportunity, or building a local fulfillment network.",[["Entrepreneurs","Questions about comparing a business opportunity? Start with the seller inquiry tools."],["MSME sellers","Prepare a package with clear pricing, inclusions, and support details."],["FLAME PH members","Ask your chapter about programs and operator opportunities."],["Email","Add the verified NegosyoDepot support email before launch."]]]};let d=pages[path]||pages["/resources"];return `<section class="page-hero"><div class="container"><div class="breadcrumbs">Home / ${routeNames[path]}</div><div class="section-kicker">NegosyoDepot · FLAME PH</div><h1>${d[0]}</h1><p>${d[1]}</p></div></section><section class="section" style="padding-top:10px"><div class="container category-grid">${d[2].map((c,i)=>`<article class="category-card"><div class="category-icon">${["✦","↗","✓","⌂","▦"][i%5]}</div><strong>${c[0]}</strong><small>${c[1]}</small></article>`).join("")}</div></section>`}
function page(){let [path,...rest]=location.hash.slice(1).split("?");if(!path)path="/";current=path;let query=rest.join("?");let body;if(path==="/")body=home();else if(path==="/explore")body=explore(query);else if(path.startsWith("/opportunity/"))body=opportunity(path.split("/")[2]);else if(path==="/find")body=finder();else if(path==="/compare")body=compare();else if(path==="/grow")body=grow();else if(path==="/scale")body=scale();else if(path==="/sell-business")body=sellBusinessPage();else if(path==="/funder-finder")body=funderFinderPage();else if(path==="/investor-funder")body=investorFunderPage();else if(path==="/faq")body=faqPage();else if(path==="/looking-for")body=lookingForPage();else if(path==="/fulfillment")body=fulfillment();else if(path.startsWith("/fulfillment/"))body=fulfillmentInfo(path);else if(path==="/partners")body=partners();else if(path==="/membership")body=membership();else if(path==="/ai")body=ai();else if(path==="/login")body=login();else if(path==="/post")body=post();else if(path==="/dashboard")body=dashboard();else if(path==="/profile")body=memberProfilePage();else if(path==="/install")body=installPage();else body=infoPage(path);layout(body);window.scrollTo(0,0);let q=new URLSearchParams(query);if(path==="/login"&&q.get("identity")){requestAnimationFrame(()=>{let field=document.getElementById("authInput");if(field){field.value=q.get("identity");if(q.get("method")==="mobile")document.querySelector('[data-auth-mode="mobile"]')?.click();let invite=document.getElementById("authInvite");if(invite)invite.value=q.get("invite")||""}})}else if(q.get("section")){requestAnimationFrame(()=>document.getElementById(q.get("section"))?.scrollIntoView({behavior:"smooth"}))}}
function toast(s){let t=document.getElementById("toast");if(!t)return;t.textContent=s;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2400)}
function saved(){return JSON.parse(localStorage.getItem("nd_saved")||"[]")}function compared(){return JSON.parse(localStorage.getItem("nd_compare")||"[]")}
function bindWorkspaceTools(){const form=document.getElementById("memberProfileForm");if(!form)return;const fields=[...form.querySelectorAll("input[name],select[name],textarea[name]")],preview={displayName:"profilePreviewName",businessName:"profilePreviewBusiness",about:"profilePreviewAbout",industry:"profilePreviewIndustry",location:"profilePreviewLocation",businessStage:"profilePreviewStage",offering:"profilePreviewOffering",seeking:"profilePreviewSeeking"};const collect=()=>Object.fromEntries(fields.map(el=>[el.name,el.type==="checkbox"?el.checked:el.value.trim()]));const update=()=>{const p=collect(),pct=profileCompletion(p);document.getElementById("profileCompletionLabel").textContent=`${pct}%`;document.getElementById("profileProgressBar").style.width=`${pct}%`;document.querySelector('[role="progressbar"]').setAttribute("aria-valuenow",String(pct));Object.entries(preview).forEach(([key,id])=>{const el=document.getElementById(id);if(el)el.textContent=p[key]||({displayName:"Your name",businessName:p.memberType||"Your business or role",about:"Add a short introduction so people can understand what you do.",industry:"Industry",location:"Location",businessStage:"Business stage",offering:"Add products, services, capacity, or experience.",seeking:"Describe the connection that would help you grow."}[key])});document.getElementById("profileAvatar").textContent=(p.displayName||p.businessName||"N").trim().slice(0,1).toUpperCase()};fields.forEach(el=>el.addEventListener("input",update));fields.forEach(el=>el.addEventListener("change",update));form.addEventListener("submit",e=>{e.preventDefault();const status=document.getElementById("profileSaveStatus");if(!document.getElementById("profileConsent").checked){status.textContent="Please confirm that you understand this profile stays private on this device.";return}try{localStorage.setItem(profileKey,JSON.stringify(collect()));status.textContent="Profile saved on this device. It is private and has not been published.";toast("Private profile preview saved")}catch{status.textContent="Could not save in this browser. Copy your profile details before leaving."}})}
function bindCommon(){document.querySelectorAll("[data-save]").forEach(b=>{let ids=saved();if(ids.includes(b.dataset.save))b.classList.add("saved"),b.textContent="♥";b.onclick=()=>{let a=saved();a=a.includes(b.dataset.save)?a.filter(x=>x!==b.dataset.save):[...a,b.dataset.save];localStorage.setItem("nd_saved",JSON.stringify(a));b.classList.toggle("saved");b.textContent=b.classList.contains("saved")?"♥":"♡";toast(b.classList.contains("saved")?"Saved to your opportunities":"Removed from saved")}});document.querySelectorAll("[data-compare]").forEach(b=>b.onclick=()=>{let a=compared();if(a.includes(b.dataset.compare)){toast("Already in your comparison");return}if(a.length>=4){toast("Compare up to four opportunities at a time");return}a.push(b.dataset.compare);localStorage.setItem("nd_compare",JSON.stringify(a));toast("Added to comparison");if(current==="/compare")page()});document.querySelectorAll("[data-uncompare]").forEach(b=>b.onclick=()=>{localStorage.setItem("nd_compare",JSON.stringify(compared().filter(x=>x!==b.dataset.uncompare)));page()});document.querySelectorAll("[data-reset]").forEach(b=>b.onclick=()=>location.hash="#/explore");document.querySelectorAll("[data-inquire]").forEach(b=>b.onclick=()=>modal(`Ask about ${b.dataset.inquire}`,"Sign in to send a message to the seller. Your question should be clear about package inclusions, location availability, and current terms.","Continue to sign in","#/login"));document.querySelectorAll("[data-report]").forEach(b=>b.onclick=()=>modal("Report this listing","In a connected platform, this action would open a private report form with evidence upload and moderation follow-up.","Sign in","#/login"));document.querySelectorAll("[data-provider]").forEach(b=>b.onclick=()=>modal("Request a fulfillment quote",`${b.dataset.provider} is illustrative demo data. Approved provider availability, rates, and capacity need to be configured before requesting a live quote.`,"Browse opportunities","#/fulfillment"));bindPageForms();bindFulfillmentTools()}
function modal(title,body,action,href){let box=document.createElement("div");box.className="modal-backdrop";box.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close">×</button><div class="section-kicker">NegosyoDepot</div><h2>${esc(title)}</h2><p>${esc(body)}</p><a class="btn btn-primary" href="${esc(href)}">${esc(action)}</a></div>`;document.body.append(box);box.onclick=e=>{if(e.target===box||e.target.closest(".modal-close"))box.remove()}}
function bindPageForms(){document.getElementById("homeSearch")?.addEventListener("submit",e=>{e.preventDefault();let f=new FormData(e.currentTarget);location.hash=`/explore?q=${encodeURIComponent(f.get("q")||"")}&max=${f.get("cap")||""}`});let applyExplore=()=>{let q=(document.getElementById("exploreQuery")?.value||"").toLowerCase(),cat=document.getElementById("exploreCategory")?.value||"",max=document.querySelector('[name="budget-filter"]:checked')?.value||new URLSearchParams(location.hash.split("?")[1]||"").get("max")||"",regions=[...document.querySelectorAll('[name="region-filter"]:checked')].map(x=>x.value),models=[...document.querySelectorAll('[name="model-filter"]:checked')].map(x=>x.value),sort=document.getElementById("exploreSort")?.value;let rows=listings.filter(x=>(!q||(x.name+" "+x.cat+" "+x.desc).toLowerCase().includes(q))&&(!cat||x.cat===cat)&&(!max||x.price<=Number(max))&&(!regions.length||regions.includes(x.region))&&(!models.length||models.some(m=>x.model.toLowerCase()===m.toLowerCase())));if(sort==="low")rows.sort((a,b)=>a.price-b.price);if(sort==="high")rows.sort((a,b)=>b.price-a.price);let grid=document.getElementById("listingGrid");if(grid)grid.innerHTML=rows.length?rows.map(card).join(""):`<div class="empty"><h3>No matches yet</h3><p>Try a broader budget, category, or location.</p><button class="btn btn-soft" data-reset>Clear filters</button></div>`;let count=document.getElementById("resultCount");if(count)count.textContent=`${rows.length} opportunities`;bindListingControls(grid||document)};if(current==="/explore"){document.getElementById("exploreQuery")?.addEventListener("input",applyExplore);document.getElementById("exploreCategory")?.addEventListener("change",applyExplore);document.getElementById("exploreSort")?.addEventListener("change",applyExplore);document.querySelectorAll('[name="budget-filter"],[name="region-filter"],[name="model-filter"]').forEach(x=>x.addEventListener("change",applyExplore));applyExplore()}document.getElementById("finderForm")?.addEventListener("submit",e=>{e.preventDefault();let max=Number(document.getElementById("fBudget").value),reg=document.getElementById("fLocation").value,model=document.getElementById("fModel").value,cat=document.getElementById("fInterest").value;let rows=listings.filter(x=>x.price<=max&&(reg==="Anywhere"||x.region===reg)&&(model==="Any model"||x.model.toLowerCase()===model.toLowerCase())&&(cat==="Any category"||x.cat===cat));document.getElementById("finderResults").innerHTML=`<div class="result-box"><h3>Your sample shortlist</h3><p>Based on the preferences you selected. Confirm price, capital needs, and fit with each seller.</p>${rows.length?rows.map(x=>`<p>→ <a class="link-arrow" href="#/opportunity/${x.id}">${x.name} · ${money(x.price)} · ${x.city}</a></p>`).join(""):`<p>No sample listing matches every selection. Try broadening your budget or location.</p>`}</div>`});document.getElementById("chatForm")?.addEventListener("submit",e=>{e.preventDefault();let input=e.currentTarget.prompt,msg=input.value.trim();if(!msg)return;let pane=document.getElementById("chatMessages");pane.innerHTML=`<div class="chat-msg user"></div><div class="chat-msg">This preview cannot access live listings yet. For a useful next step, compare each seller's total startup capital, recurring costs, location, training, and supply support. You can explore the sample opportunities on this site or connect an approved AI service for grounded recommendations.</div>`+pane.innerHTML;pane.querySelector(".chat-msg.user").textContent=msg;input.value=""});document.querySelectorAll("[data-ai-prompt]").forEach(b=>b.onclick=()=>{document.querySelector("#chatForm input").value=b.dataset.aiPrompt;document.querySelector("#chatForm input").focus()});document.querySelectorAll("[data-auth-mode]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-auth-mode]").forEach(x=>x.classList.remove("active"));b.classList.add("active");let mobile=b.dataset.authMode==="mobile",inp=document.getElementById("authInput");inp.type=mobile?"tel":"email";inp.placeholder=mobile?"+63 9XX XXX XXXX":"you@example.com";document.getElementById("authLabel").textContent=mobile?"Mobile number":"Email address";document.getElementById("authHelp").textContent=mobile?"We’ll send a one-time SMS code.":"We’ll send a one-time sign-in code."});document.getElementById("signupForm")?.addEventListener("submit",e=>{e.preventDefault();modal("Signup integration needed","This preview cannot send verification codes or create a FLAMEPH Member ID. Connect Supabase Auth, email/SMS delivery, and the shared member directory to activate signup.","Return to NegosyoDepot","#/" )});document.getElementById("postForm")?.addEventListener("submit",e=>{e.preventDefault();modal("Sign in to save your draft","Seller listings and moderation require a verified FLAMEPH member account.","Continue to sign in","#/login")})}
window.addEventListener("hashchange",page);window.addEventListener("DOMContentLoaded",page);if(document.readyState!=="loading")page();
function investorFunderPage(){const offers=[["Seed equity","Angel / early-stage","₱250k–₱2m","Consumer, food, climate","Traction, founder commitment, cap table"],["Inventory finance","Financier / lender","₱100k–₱5m","Retail, distribution","Purchase orders, repayment plan, verified business"],["Strategic co-owner","Corporate partner","₱500k–₱10m","Manufacturing, services","Operating role, governance, milestones"]];return `<section class="page-hero investor-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / Investor/Funder</div><div class="section-kicker">A clearer capital marketplace</div><h1>Investors and funders: publish your mandate. MSMEs: find a fit.</h1><p>Create a verified organization profile, describe the capital you can provide, and state your requirements so business owners can approach you with relevant opportunities.</p><div class="hero-actions"><a class="btn btn-primary" href="#/login?role=funder">Create investor/funder account</a><a class="btn btn-outline" href="#investor-offers">Browse sample offers</a></div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">For angels, VCs, banks, financiers, grants, and strategic partners</div><h2>Choose how you participate.</h2></div><p>NegosyoDepot is a discovery and introduction layer. It does not receive funds, make investment recommendations, or close transactions.</p></div><div class="category-grid investor-types"><article class="category-card"><div class="category-icon">✦</div><strong>Angel investor</strong><small>Early-stage equity, convertible instruments, mentorship, and introductions.</small></article><article class="category-card"><div class="category-icon">↗</div><strong>Venture capital</strong><small>Institutional equity for scalable businesses that match a published thesis.</small></article><article class="category-card"><div class="category-icon">₱</div><strong>Bank or financier</strong><small>Loans, lines, equipment finance, invoice or inventory funding subject to approval.</small></article><article class="category-card"><div class="category-icon">◎</div><strong>Strategic partner</strong><small>Co-ownership, distribution capital, supplier credit, or operating partnerships.</small></article></div></div></section><section class="section" id="investor-offers"><div class="container"><div class="section-head"><div><div class="section-kicker">Offer directory</div><h2>Example offers and requirements.</h2></div><a class="btn btn-soft" href="#/login?role=funder">Post your offer</a></div><div class="offer-grid">${offers.map(o=>`<article class="offer-card"><span class="listing-badge">${o[1]}</span><h3>${o[0]}</h3><strong>${o[2]}</strong><p>${o[3]}</p><small><b>Typical requirements:</b> ${o[4]}</small><a class="link-arrow" href="#/login?role=funder">View funder profile →</a></article>`).join("")}</div></div></section><section class="section section-white" id="funder-onboarding"><div class="container two-col"><div><div class="section-kicker">Funder onboarding</div><h2>Build a credible profile in five steps.</h2><div class="guide-step-grid compact-guides">${["Create a FLAMEPH Member ID and choose Investor/Funder.","Verify the organization, authorized representative, and regulated status where applicable.","Publish your mandate: capital type, ticket range, geography, sectors, stage, and exclusions.","State requirements, diligence materials, process, decision timeline, and risk disclosures.","Respond inside the platform and move diligence or agreements to secure, appropriate channels."].map((x,i)=>`<article class="guide-step"><span class="guide-step-number">${String(i+1).padStart(2,"0")}</span><div><p>${x}</p></div></article>`).join("")}</div></div><form class="panel funder-offer-form" id="funderOfferForm"><h3>Draft an offer for review</h3><p class="fine-print">This browser draft is private and is not a public solicitation.</p><div class="field"><label for="offerOrg">Organization or funder name</label><input id="offerOrg" required placeholder="Example: Mabuhay Growth Partners"></div><div class="field"><label for="offerRole">Funder type</label><select id="offerRole"><option>Angel investor</option><option>Venture capital fund</option><option>Bank or financing company</option><option>Corporate / strategic partner</option><option>Grant or impact fund</option></select></div><div class="field"><label for="offerType">Offer type</label><select id="offerType"><option>Equity investment</option><option>Convertible instrument</option><option>Loan or credit line</option><option>Inventory or purchase-order finance</option><option>Revenue share</option><option>Co-ownership / strategic partnership</option><option>Grant or concessionary funding</option></select></div><div class="field"><label for="offerRange">Ticket range and currency</label><input id="offerRange" required placeholder="₱250,000–₱2,000,000"></div><div class="field"><label for="offerFit">Sectors, locations, and stage</label><input id="offerFit" required placeholder="Food, manufacturing · Philippines · revenue-generating"></div><div class="field"><label for="offerRequirements">Requirements and diligence materials</label><textarea id="offerRequirements" rows="3" required placeholder="Traction, financial statements, permits, collateral, governance, or other criteria"></textarea></div><div class="field"><label for="offerDisclosure">Terms, risks, fees, and disclosures</label><textarea id="offerDisclosure" rows="3" required placeholder="Explain return structure, interest or dilution, fees, security, term, and key risks"></textarea></div><button class="btn btn-primary" type="submit">Save offer draft</button><span class="fine-print" id="offerSaveStatus" role="status"></span></form></div></section><section class="section" id="funder-landing"><div class="container"><div class="section-head"><div><div class="section-kicker">Mini landing page builder</div><h2>Give your fund a focused public introduction.</h2></div><p>Use a concise page to explain your thesis, process, and next step. A production version should be approved and published by the account owner.</p></div><form class="panel landing-builder" id="funderLandingForm"><div class="field"><label for="landingName">Brand or fund name</label><input id="landingName" required placeholder="Your fund, bank, or financing brand"></div><div class="field"><label for="landingTagline">One-line positioning</label><input id="landingTagline" required placeholder="Patient capital for Philippine food and manufacturing MSMEs"></div><div class="field"><label for="landingOffer">What you offer and who you back</label><textarea id="landingOffer" rows="3" required placeholder="Capital type, ticket size, stage, sectors, geography, and differentiator"></textarea></div><div class="field"><label for="landingCta">Preferred next step</label><input id="landingCta" required placeholder="Request an introductory call"></div><button class="btn btn-primary" type="submit">Preview funder landing page</button></form><div id="landingPreview" class="landing-preview" hidden></div></div></section><section class="section section-white" id="funder-rules"><div class="container legal-guide"><div class="section-kicker">Philippine compliance guide</div><h2>Publish responsibly and verify before you transact.</h2><p class="trust-note">This is a practical orientation, not legal, tax, investment, or lending advice. Rules depend on the instrument, audience, entity, and activity. Ask Philippine counsel and the relevant regulator before soliciting funds or accepting money.</p><div class="legal-grid"><article><h3>Equity, co-ownership, and profit interests</h3><p>Shares, participation, investment contracts, and interests in a profit-making venture can be securities under the Securities Regulation Code. Public offers and intermediated crowdfunding may trigger registration, disclosure, intermediary, and investor-qualification requirements.</p><a href="https://lawphil.net/statutes/repacts/ra2000/ra_8799_2000.html" target="_blank" rel="noreferrer">Read R.A. 8799 →</a></article><article><h3>Crowdfunding and online offers</h3><p>SEC Memorandum Circular No. 14, s. 2019 governs crowdfunding of securities and describes funding portals and their limits. NegosyoDepot should remain a lead-generation and information layer unless the operating model is separately reviewed and authorized.</p><a href="https://www.sec.gov.ph/wp-content/uploads/2019Advisory/2019MCNo14.pdf" target="_blank" rel="noreferrer">Read SEC MC No. 14 →</a></article><article><h3>Loans and financing</h3><p>Lending companies need SEC authority under R.A. 9474; financing companies are covered by R.A. 8556 and related SEC requirements. BSP-supervised institutions have separate licensing and consumer-protection obligations. Show authority details, effective interest, fees, security, repayment, and complaints channels.</p><a href="https://www.sec.gov.ph/services-2/company-2/secondary-registration/lending-companies/" target="_blank" rel="noreferrer">SEC lending and financing requirements →</a></article><article><h3>Consumer protection, AML, and privacy</h3><p>Use transparent disclosures, fair communications, identity and beneficial-owner checks, complaint handling, and privacy controls. Never ask users to send money to personal accounts or upload sensitive documents to an unverified contact.</p><a href="https://www.bsp.gov.ph/Pages/InclusiveFinance/FinancialProductsServices.aspx" target="_blank" rel="noreferrer">BSP financial consumer guidance →</a></article></div><div class="compliance-checklist"><h3>Before an MSME sends money or signs</h3><ul><li>Verify the legal entity, authorized representative, SEC/BSP or other regulator status, and official domain.</li><li>Match the instrument to a written agreement: equity, loan, revenue share, co-ownership, grant, or purchase-order finance.</li><li>Review valuation, dilution, interest, effective cost, fees, collateral, repayment, control rights, default, exit, and dispute terms.</li><li>Request current financials, use of funds, assumptions, risk factors, and references; never rely on guaranteed returns.</li><li>Use independent legal, tax, and financial advice before committing.</li></ul></div></div></section>`}
function bindInvestorTools(){const offer=document.getElementById("funderOfferForm");if(offer){try{const saved=JSON.parse(localStorage.getItem("nd_funder_offer_draft")||"{}");Object.entries(saved).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.value=v})}catch{}offer.addEventListener("submit",e=>{e.preventDefault();const ids=["offerOrg","offerRole","offerType","offerRange","offerFit","offerRequirements","offerDisclosure"],saved=Object.fromEntries(ids.map(id=>[id,document.getElementById(id).value.trim()]));try{localStorage.setItem("nd_funder_offer_draft",JSON.stringify(saved));document.getElementById("offerSaveStatus").textContent="Offer draft saved on this device. Sign in as Investor/Funder to submit for review."}catch{document.getElementById("offerSaveStatus").textContent="Storage unavailable; copy your details before leaving."}})}const landing=document.getElementById("funderLandingForm");if(landing){landing.addEventListener("submit",e=>{e.preventDefault();const name=document.getElementById("landingName").value.trim(),tag=document.getElementById("landingTagline").value.trim(),offer=document.getElementById("landingOffer").value.trim(),cta=document.getElementById("landingCta").value.trim(),preview=document.getElementById("landingPreview");preview.hidden=false;preview.innerHTML=`<div class="landing-preview-inner"><span class="section-kicker">Investor/Funder profile</span><h2>${esc(name)}</h2><h3>${esc(tag)}</h3><p>${esc(offer)}</p><a class="btn btn-primary" href="#/login?role=funder">${esc(cta||"Start a conversation")} →</a><p class="fine-print">Preview only · Verify your organization and disclosures before publishing.</p></div>`})}}

function bindListingControls(root){root.querySelectorAll('[data-save]').forEach(b=>{let ids=saved();if(ids.includes(b.dataset.save))b.classList.add('saved'),b.textContent='♥';b.onclick=()=>{let a=saved();a=a.includes(b.dataset.save)?a.filter(x=>x!==b.dataset.save):[...a,b.dataset.save];localStorage.setItem('nd_saved',JSON.stringify(a));b.classList.toggle('saved');b.textContent=b.classList.contains('saved')?'♥':'♡';toast(b.classList.contains('saved')?'Saved to your opportunities':'Removed from saved')}});root.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{let a=compared();if(a.includes(b.dataset.compare)){toast('Already in your comparison');return}if(a.length>=4){toast('Compare up to four opportunities at a time');return}a.push(b.dataset.compare);localStorage.setItem('nd_compare',JSON.stringify(a));toast('Added to comparison');if(current==='/compare')page()});root.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>location.hash='#/explore')}
